from typing import Dict, List, Tuple


class Gradebook:
    def __init__(self) -> None:
        # assignment_name -> (weight, kind)
        self._assignments: Dict[str, Tuple[float, str]] = {}
        # student_name -> {assignment_name: grade}
        self._grades: Dict[str, Dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self._assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if student not in self._grades:
            self._grades[student] = {}
        self._grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if not self._assignments:
            return 0.0

        student_grades = self._grades.get(student, {})

        # Collect assignments and effective grades (default 2.0 if not recorded)
        homeworks: List[Tuple[float, float]] = []  # (grade, weight)
        quizzes: List[Tuple[float, float, str]] = []  # (grade, weight, name)

        for name, (weight, kind) in self._assignments.items():
            grade = student_grades.get(name, 2.0)
            if kind == "quiz":
                quizzes.append((grade, weight, name))
            else:
                homeworks.append((grade, weight))

        # If more than one quiz exists, drop the one with the lowest grade
        if len(quizzes) > 1:
            # Find the quiz with the minimum grade.
            # In case of ties, any single lowest-grade quiz is dropped.
            min_quiz = min(quizzes, key=lambda item: item[0])
            quizzes.remove(min_quiz)

        total_weighted_sum = sum(grade * weight for grade, weight in homeworks)
        total_weight = sum(weight for _, weight in homeworks)

        total_weighted_sum += sum(grade * weight for grade, weight, _ in quizzes)
        total_weight += sum(weight for _, weight, _ in quizzes)

        if total_weight == 0:
            return 0.0

        return round(total_weighted_sum / total_weight, 2)
```

